// n8n Code node: Classify
// Works out what kind of message this is and normalises the fields the rest
// of the workflow needs. One item in, one item out.

const ALLOWED_CHAT_ID = '{{TELEGRAM_CHAT_ID}}';   // paste your chat id here after the first /start, e.g. '123456789'

const upd = $input.first().json || {};
const cb = upd.callback_query || null;                 // inline keyboard tap (night quiz)
const msg = cb ? (cb.message || {}) : (upd.message || {});
const chatId = String(msg.chat && msg.chat.id || '');
const text = cb ? '' : (msg.text || msg.caption || '').trim();
const dt = DateTime.fromSeconds(msg.date || Math.floor(Date.now() / 1000)).setZone('Europe/London');
const dateISO = dt.toISODate();
const timeHM = dt.toFormat('HH:mm');

// tape sites -> measurements tab column
const SITES = {
  'neck': 'neck_cm', 'chest': 'chest_cm', 'waist': 'waist_navel_cm', 'hips': 'hips_cm', 'hip': 'hips_cm',
  'shoulders': 'shoulders_cm', 'shoulder': 'shoulders_cm',
  'l arm': 'l_arm_cm', 'left arm': 'l_arm_cm', 'r arm': 'r_arm_cm', 'right arm': 'r_arm_cm',
  'l thigh': 'l_thigh_cm', 'left thigh': 'l_thigh_cm', 'r thigh': 'r_thigh_cm', 'right thigh': 'r_thigh_cm',
  'l calf': 'l_calf_cm', 'left calf': 'l_calf_cm', 'r calf': 'r_calf_cm', 'right calf': 'r_calf_cm',
};

let kind = 'unknown';
let payload = {};

if (ALLOWED_CHAT_ID && chatId !== ALLOWED_CHAT_ID) {
  kind = 'blocked';
} else if (cb) {
  kind = 'callback';
  payload = { callback_id: String(cb.id), data: cb.data || '', message_id: msg.message_id, message_text: msg.text || '' };
} else if (/^\/start|^\/help|^help$/i.test(text)) {
  kind = 'help';
} else if (msg.photo && msg.photo.length) {
  // label photo: Telegram sends several sizes, take the largest.
  // An album (several photos sent together) arrives as separate messages sharing media_group_id,
  // with the caption on only one of them; group_key lets the label branch merge them.
  const best = msg.photo[msg.photo.length - 1];
  kind = 'label';
  const mg = msg.media_group_id ? String(msg.media_group_id) : null;
  payload = { file_id: best.file_id, caption: text, message_id: msg.message_id, media_group_id: mg, group_key: mg ? 'g:' + mg : 'm:' + msg.message_id };
} else if (msg.voice || msg.audio) {
  kind = 'food';
  payload = { voice: true, file_id: (msg.voice || msg.audio).file_id };
} else if (/^no label\b/i.test(text)) {
  kind = 'nolabel';
  payload = { text: text.replace(/^no label\b[:\s]*/i, '').trim() };
} else if (text) {
  const w = text.match(/^(?:weight|w)?\s*[:=]?\s*(\d{2,3}(?:\.\d{1,2})?)\s*(?:kg)?$/i);
  const tapeParts = text.split(/[,\n]+/).map(s => s.trim()).filter(Boolean);
  const tape = {};
  let allTape = tapeParts.length > 0;
  for (const p of tapeParts) {
    const m = p.match(/^([a-z ]+?)\s*[:=]?\s*(\d{2,3}(?:\.\d{1,2})?)\s*(?:cm)?$/i);
    const col = m && SITES[m[1].trim().toLowerCase()];
    if (!col) { allTape = false; break; }
    tape[col] = parseFloat(m[2]);
  }
  const note = text.match(/^note[:\s]+(.+)$/is);
  const stool = text.match(/^(?:stool|poo|poop|bristol|\u{1F4A9})\s*[:=]?\s*([1-7])\b\s*(.*)$/isu);
  const tmpl = /\b(push|pull|legs?)\b/i.test(text) && /\b(template|plan|note|workout|session|give me|doing|what should)\b/i.test(text) && text.split(/\s+/).length <= 14 ? text.match(/\b(push|pull|legs?)\b/i) : null;
  // exact day-type override: "push today", "rest day", "today: legs"
  let dayT = text.match(/^(?:today(?:'s| is)?[:\s]+)?(push|pull|legs?|cardio|rest)(?:\s*day)?(?:\s+today)?[.!]?$/i);
  // loose day-type intent (12 Oct): a short statement naming a day with an intent word, e.g. "nah I wanna do push",
  // "push tonight, cardio tomorrow", "I'm doing legs instead". Not a question, not a choice ("push or pull?"), not a set line.
  if (!dayT && !tmpl && !/[?]/.test(text) && !/\bor\b/i.test(text) && text.split(/\s+/).length <= 12 && !/\d\s*(kg)?\s*x\s*\d/i.test(text)) {
    const kept = text.split(/[,.;\n]+/).filter(s => !/\btomorrow\b/i.test(s)).join(' ');
    const day = kept.match(/\b(push|pull|legs?|cardio|rest)\b/i);
    if (day && /\b(today|tonight|now|instead|lift|lifting|train|training|do|doing|wanna|want|going|gonna|gunna|day|session|it'?s|is|time|swap|switch|change)\b/i.test(kept)) dayT = day;
  }
  if (w) {
    kind = 'weight';
    payload = { weight_kg: parseFloat(w[1]) };
  } else if (allTape) {
    kind = 'tape';
    payload = tape;
  } else if (stool) {
    kind = 'stool';                                    // "stool 4", "poo 6 after the curry" -> stool_log
    payload = { bristol_type: parseInt(stool[1], 10), note: (stool[2] || '').trim() || null };
  } else if (note) {
    kind = 'note';                                     // "note: slept badly" -> daily.note (closes the night quiz if it is on the note step)
    payload = { text: note[1].trim() };
  } else if (tmpl) {
    kind = 'template';                                 // "legs template", "give me my pull plan" -> Keep-style note for that day, with last session's numbers
    payload = { day_type: tmpl[1].toLowerCase() === 'leg' ? 'legs' : tmpl[1].toLowerCase() };
  } else if (dayT) {
    kind = 'daytype';                                  // "pull today", "rest day", "today: legs", "wanna do push" -> daily.day_type override
    const t = dayT[1].toLowerCase();
    payload = { day_type: t === 'leg' ? 'legs' : t };
  } else if (/^(yes|y|yep|yeah|correct|ok|okay|all good|no|nope|change)[.!]?$/i.test(text)) {
    kind = 'quizreply';                                // typed answer to the night quiz's first step
    payload = { text };
  } else if (/^\s*(food|ate|eat|meal|breakfast|lunch|dinner|snack)\b/i.test(text)) {
    kind = 'food';
    payload = { voice: false, text: text.replace(/^\s*food\b[:\s]*/i, '').trim() };
  } else if (/\d\s*(kg)?\s*x\s*\d|^\s*x\s*\d|\bbw\s*x/im.test(text) || /^\d+\s+[a-z]/im.test(text)) {
    kind = 'workout';
  } else {
    kind = 'question';   // any other text goes to the coach as a free-form question
    payload = { text };
  }
}

return [{ json: { kind, chatId, dateISO, timeHM, text, payload } }];

// ---------- shared workout library (parser + template) ----------
// Embedded in the n8n Code nodes "Parse and compare" and "Build template".
// Keep the two copies identical (the only difference is the node body at the end).

const DEFAULT_GYM = '{{DEFAULT_GYM}}';
const SOURCE = 'telegram';
const WARMUP_RATIO = 0.4;   // a set under 40% of the exercise's top load that session is a warm-up: no volume, no PB
const SESSION_SET_CAP = 20; // working sets per session, the user's hard ceiling (22 Oct): the template trims to fit

const STARTER_ALIASES = {
  'pull ups': 'Weighted Pull Up', 'pull up': 'Weighted Pull Up', 'pullups': 'Weighted Pull Up',
  'weighted pull ups': 'Weighted Pull Up', 'wide grip pull ups': 'Weighted Pull Up',
  'chin ups': 'Weighted Chin Up', 'chin up': 'Weighted Chin Up', 'chins': 'Weighted Chin Up',
  'weighted chin ups': 'Weighted Chin Up',
  'dips': 'Weighted Dip', 'dip': 'Weighted Dip', 'weighted dips': 'Weighted Dip',
  'squat': 'Back Squat', 'squats': 'Back Squat', 'back squat': 'Back Squat', 'back squats': 'Back Squat',
  'front squat': 'Front Squat', 'front squats': 'Front Squat',
  'leg press': 'Leg Press', 'leg extension': 'Leg Extension', 'leg extensions': 'Leg Extension',
  'leg curl': 'Leg Curl', 'leg curls': 'Leg Curl', 'lying leg curl': 'Leg Curl', 'seated leg curl': 'Leg Curl',
  'rdl': 'Romanian Deadlift', 'rdls': 'Romanian Deadlift', 'romanian deadlift': 'Romanian Deadlift',
  'deadlift': 'Deadlift', 'deadlifts': 'Deadlift',
  'calf raise': 'Calf Raise', 'calf raises': 'Calf Raise', 'calves': 'Calf Raise',
  'hip abductor': 'Hip Abductor', 'hip abductors': 'Hip Abductor', 'abductor': 'Hip Abductor', 'abductors': 'Hip Abductor',
  'hanging leg raise': 'Hanging Leg Raise', 'hanging leg raises': 'Hanging Leg Raise',
  'bench': 'Barbell Bench Press', 'bench press': 'Barbell Bench Press', 'flat bench': 'Barbell Bench Press',
  'incline bench': 'Incline Bench Press', 'incline': 'Incline Bench Press',
  'dumbbell press': 'Dumbbell Bench Press', 'db press': 'Dumbbell Bench Press', 'flat dumbbell press': 'Dumbbell Bench Press',
  'incline dumbbell press': 'Incline Dumbbell Press', 'incline db press': 'Incline Dumbbell Press',
  'shoulder press': 'Dumbbell Shoulder Press', 'db shoulder press': 'Dumbbell Shoulder Press',
  'ohp': 'Overhead Press', 'military press': 'Overhead Press', 'overhead press': 'Overhead Press',
  'lateral raise': 'Lateral Raise', 'lateral raises': 'Lateral Raise', 'side raise': 'Lateral Raise', 'side raises': 'Lateral Raise',
  'cable lateral raise': 'Cable Lateral Raise', 'cable raises': 'Cable Lateral Raise',
  'front raise': 'Front Raise', 'front raises': 'Front Raise',
  'rear delt': 'Rear Delt Fly', 'rear delts': 'Rear Delt Fly', 'rear delt fly': 'Rear Delt Fly', 'reverse fly': 'Rear Delt Fly',
  'bent row': 'Bent Over Row', 'bent rows': 'Bent Over Row', 'bent over row': 'Bent Over Row', 'barbell row': 'Bent Over Row',
  'seated row': 'Seated Row', 'seated rows': 'Seated Row', 'cable row': 'Seated Row',
  'machine row': 'Machine Row', 'compound row': 'Machine Row',
  'lat pulldown': 'Lat Pulldown', 'lat pull down': 'Lat Pulldown', 'pulldown': 'Lat Pulldown',
  'preacher curl': 'Preacher Curl', 'preacher curls': 'Preacher Curl', 'preachers': 'Preacher Curl',
  'hammer curl': 'Hammer Curl', 'hammer curls': 'Hammer Curl',
  'dumbbell curl': 'Dumbbell Curl', 'db curl': 'Dumbbell Curl', 'curls': 'Dumbbell Curl',
  'barbell curl': 'Barbell Curl', 'ez curl': 'Barbell Curl',
  'skull crusher': 'Skull Crusher', 'skull crushers': 'Skull Crusher',
  'tricep pushdown': 'Tricep Pushdown', 'pushdown': 'Tricep Pushdown', 'rope pushdown': 'Tricep Pushdown', 'tricep pull down': 'Tricep Pushdown',
  'cable fly': 'Cable Crossover', 'cable flys': 'Cable Crossover', 'cable flies': 'Cable Crossover', 'cable crossover': 'Cable Crossover',
  'push ups': 'Push Up', 'press ups': 'Push Up',
  'lunges': 'Lunge', 'lunge': 'Lunge',
  'hip thrust': 'Hip Thrust', 'hip thrusts': 'Hip Thrust',
  'knee raises': 'Knee Raise', 'hanging knee raises': 'Knee Raise', 'leg raises': 'Leg Raise',
};

const EX_META = {
  'Weighted Pull Up': ['back', 'bodyweight'], 'Weighted Chin Up': ['back', 'bodyweight'],
  'Weighted Dip': ['chest', 'bodyweight'], 'Push Up': ['chest', 'bodyweight'],
  'Back Squat': ['quads', 'barbell'], 'Front Squat': ['quads', 'barbell'], 'Leg Press': ['quads', 'machine'],
  'Leg Extension': ['quads', 'machine'], 'Leg Curl': ['hamstrings', 'machine'], 'Romanian Deadlift': ['hamstrings', 'barbell'],
  'Deadlift': ['posterior chain', 'barbell'], 'Calf Raise': ['calves', 'machine'], 'Lunge': ['quads', 'dumbbell'],
  'Hip Thrust': ['glutes', 'barbell'], 'Hip Abductor': ['glutes', 'machine'], 'Hanging Leg Raise': ['core', 'bodyweight'],
  'Barbell Bench Press': ['chest', 'barbell'], 'Incline Bench Press': ['chest', 'barbell'],
  'Dumbbell Bench Press': ['chest', 'dumbbell'], 'Incline Dumbbell Press': ['chest', 'dumbbell'],
  'Cable Crossover': ['chest', 'cable'],
  'Dumbbell Shoulder Press': ['shoulders', 'dumbbell'], 'Overhead Press': ['shoulders', 'barbell'],
  'Lateral Raise': ['side delts', 'dumbbell'], 'Cable Lateral Raise': ['side delts', 'cable'],
  'Front Raise': ['front delts', 'dumbbell'], 'Rear Delt Fly': ['rear delts', 'machine'],
  'Bent Over Row': ['back', 'barbell'], 'Seated Row': ['back', 'cable'], 'Machine Row': ['back', 'machine'],
  'Lat Pulldown': ['back', 'cable'],
  'Preacher Curl': ['biceps', 'machine'], 'Hammer Curl': ['biceps', 'dumbbell'], 'Dumbbell Curl': ['biceps', 'dumbbell'],
  'Barbell Curl': ['biceps', 'barbell'],
  'Skull Crusher': ['triceps', 'barbell'], 'Tricep Pushdown': ['triceps', 'cable'],
  'Knee Raise': ['core', 'bodyweight'], 'Leg Raise': ['core', 'bodyweight'],
};

const PER_SIDE_EXERCISES = new Set(['Preacher Curl']);

const SESSION_TYPES = [
  ['push', /\b(push|chest|shoulders?|tri(ceps)?)\b/i],
  ['pull', /\b(pull|back|bi(ceps)?|arms)\b/i],
  ['legs', /\b(legs?|lower)\b/i],
];

const PROUD_RE = /[\u{1F98D}\u{1F525}\u{1F4AA}]/u;
const EFFORT_RE = /[\u{1F62E}\u{200D}\u{1F4A8}\u{1F613}\u{1F975}\u{1F630}]|\bphew\b/iu;
const PB_RE = /\*{3,}/;
const DELTA_RE = /\(\s*(\+\d+(?:\.\d+)?|-\d+(?:\.\d+)?|same)\s*\)/i;
const DIDNT_DO_RE = /\bdidn'?t\s+do\b/i;
// "3 min RP", "2 min RP ((rest periods))", "1 RP" (minutes), "90s RP", "RP 2 min"
const RP_RE = /^(?:rp\s*[:=]?\s*)?(\d+(?:\.\d+)?)\s*(min|mins|minutes|m|s|sec|secs|seconds)?\s*(?:rp|rest)\b|^rp\s*[:=]?\s*(\d+(?:\.\d+)?)\s*(min|mins|minutes|m|s|sec|secs|seconds)?/i;
// static hold: "30kg: 1:10", "30kg x 1:10", "bw 0:45", "x 45s"
const HOLD_RE = /^(?:(bw|\d+(?:\.\d+)?)\s*(kg)?\s*)?[:x]?\s*(?:(\d+):(\d{2})|(\d+)\s*s(?:ec|ecs|econds)?)\b/i;
const MODIFIER_RE = /^\(([^()]{1,30})\)\s*$/;   // "(Seated)" on its own line: a modifier for the current exercise
const TEMPLATE_LINE_RE = /^\((last|cap):/i;    // the template's own bracket lines, never data

function titleCase(s) {
  return s.replace(/\s+/g, ' ').trim().replace(/\w\S*/g, w => w[0].toUpperCase() + w.slice(1).toLowerCase());
}
function cleanRawName(s) {
  return s.replace(/^[\s\-•\*•·]+/, '').replace(/[\u{1F300}-\u{1FAFF}☀-➿]/gu, '').replace(/[:\-]+\s*$/, '').replace(/\s+/g, ' ').trim();
}
function parseDate(title, fallbackISO) {
  const m = title.match(/(\d{1,2})[\/\-.](\d{1,2})[\/\-.](\d{2,4})/);
  if (!m) return fallbackISO;
  let [, d, mo, y] = m;
  if (y.length === 2) y = '20' + y;
  return `${y}-${mo.padStart(2, '0')}-${d.padStart(2, '0')}`;
}
function sessionTypeFrom(title) {
  for (const [t, re] of SESSION_TYPES) if (re.test(title)) return t;
  return 'unknown';
}
function sumReps(str) { return str.split(/[\/&+]/).map(x => parseInt(x, 10) || 0).reduce((a, b) => a + b, 0); }

function parseRest(line) {
  const m = line.replace(/^[\s(]+|[\s)]+$/g, '').match(RP_RE);
  if (!m) return null;
  const n = parseFloat(m[1] != null ? m[1] : m[3]);
  const u = (m[2] || m[4] || 'min').toLowerCase();
  return /^s/.test(u) ? Math.round(n) : Math.round(n * 60);
}

function parseHold(line, ctxWeight) {
  let s = line.replace(/\([^)]*\)/g, ' ').trim();
  const m = s.match(HOLD_RE);
  if (!m) return null;
  if (!m[3] && !m[5]) return null;
  const secs = m[3] != null ? parseInt(m[3], 10) * 60 + parseInt(m[4], 10) : parseInt(m[5], 10);
  let w = m[1], unit = 'kg';
  if (w == null) { if (ctxWeight != null) w = ctxWeight; else { w = 0; unit = 'bw'; } }
  else if (/^bw$/i.test(w)) { w = 0; unit = 'bw'; }
  else w = parseFloat(w);
  return { weight: w, unit, reps: 0, hold_s: secs };
}

function parseSetLine(line, ctxWeight) {
  let s = line.replace(PB_RE, '').replace(DELTA_RE, '');
  s = s.replace(/\([^)]*\)/g, ' ');
  s = s.replace(/[\u{1F300}-\u{1FAFF}☀-➿]/gu, '').trim();
  if (RP_RE.test(s)) return null;
  const prose = s.match(/^(\d+)\s+[a-z][a-z ]+$/i);
  if (prose && !/x/i.test(s)) return [{ weight: 0, unit: 'bw', reps: +prose[1] }];
  const chunks = s.split(/,(?=\s*\d|\s*bw|\s*x)/i).map(c => c.trim()).filter(Boolean);
  const out = [];
  let lastWeight = ctxWeight;
  let lastUnit = ctxWeight != null ? 'kg' : null;
  for (const c of chunks) {
    const m = c.match(/^(?:(bw|\+?\d+(?:\.\d+)?)\s*(kg|lb|lbs|plates?)?\s*)?x\s*(\d+(?:\s*[\/&+]\s*\d+)*)(.*)$/i);
    if (!m) {
      const r = c.match(/^(\d+)(?:\s*[\/&+]\s*(\d+))*$/);
      if (r && lastWeight != null) { out.push({ weight: lastWeight, unit: lastUnit, reps: sumReps(c) }); continue; }
      return out.length ? out : null;
    }
    let w = m[1], unit = m[2], repsStr = m[3];
    if (w == null) { if (ctxWeight != null) { w = ctxWeight; unit = 'kg'; } else { w = 0; unit = 'bw'; } }
    else if (/^bw$/i.test(w)) { w = 0; unit = 'bw'; }
    else { w = parseFloat(w); unit = unit ? unit.toLowerCase() : 'kg'; if (unit === 'lbs') unit = 'lb'; if (/^plates?$/.test(unit)) unit = 'plates'; }
    out.push({ weight: w, unit, reps: sumReps(repsStr) });
    lastWeight = w; lastUnit = unit;
  }
  return out.length ? out : null;
}

function flagsFrom(line) {
  const d = line.match(DELTA_RE);
  let delta = '';
  if (d) delta = /same/i.test(d[1]) ? '0' : d[1];
  const noteParts = [];
  const paren = line.replace(DELTA_RE, '').match(/\(([^)]*)\)/g);
  if (paren) noteParts.push(...paren.map(p => p.slice(1, -1).trim()).filter(Boolean));
  if (PB_RE.test(line)) noteParts.push('**** PB');
  const rp = line.replace(/\([^)]*\)/g, '').match(/x\s*(\d+(?:\s*[\/&+]\s*\d+)+)/i);
  if (rp) noteParts.push('rest-pause ' + rp[1].replace(/\s+/g, ''));
  return { pb_flag: PB_RE.test(line) ? 1 : 0, proud: PROUD_RE.test(line) ? 1 : 0, effort: EFFORT_RE.test(line) ? 1 : 0, delta_vs_prev: delta, note: noteParts.join('; ') };
}

function normKey(k) { return k.toLowerCase().replace(/dumbell/g, 'dumbbell').replace(/flys/g, 'fly').replace(/flies/g, 'fly').replace(/[^a-z0-9 ]/g, '').replace(/\s+/g, ' ').trim(); }

function resolveExercise(raw, aliases) {
  const key = normKey(raw);
  if (aliases[key]) return { exercise: aliases[key], known: true };
  const stripped = key.replace(/\b(wide|close|narrow|neutral|underhand|overhand|grip|seated|standing|lying|machine|cable)\b/g, '').replace(/\s+/g, ' ').trim();
  if (stripped && aliases[stripped]) return { exercise: aliases[stripped], known: true };
  return { exercise: titleCase(raw), known: false };
}

// Does the first line look like a session title rather than an exercise header?
function isTitleLine(line) {
  const hasDate = /\d{1,2}[\/\-.]\d{1,2}[\/\-.]\d{2,4}/.test(line);
  if (hasDate) return true;
  return /^(push|pull|legs?|upper|lower|arms|chest|back|shoulders)\b\s*(day|session)?\s*:?\s*$/i.test(line);
}

// Warm-up rule over one exercise's sets in one session (the user, 11 and 22 Oct): a set under 40% of the top load is a
// warm-up, and on a weighted calisthenic (dips, pull-ups, chins) a bodyweight set is the warm-up whenever weighted sets follow.
function flagWarmups(group) {
  const work = group.filter(s => !s.hold_s);
  const weighted = work.some(s => s.unit !== 'bw');
  const top = Math.max(0, ...work.map(s => s.unit === 'bw' ? 0 : num(s.weight)));
  for (const s of group) {
    if (s.hold_s) continue;
    if (s.unit === 'bw') { if (weighted) s.warmup = true; continue; }
    if (top > 0 && num(s.weight) < WARMUP_RATIO * top) s.warmup = true;
  }
}

function parseWorkout(text, msgDateISO, opts = {}) {
  const gym = opts.gym || DEFAULT_GYM;
  const aliases = {};
  for (const src of [STARTER_ALIASES, opts.aliases || {}]) for (const [k, v] of Object.entries(src)) aliases[normKey(k)] = v;
  const meta = Object.assign({}, EX_META, opts.meta || {});
  const warnings = [];

  const rawLines = text.replace(/\r/g, '').split('\n');
  const lines = [];
  let depth = 0;
  for (const l of rawLines) {
    const opens = (l.match(/\(/g) || []).length;
    const closes = (l.match(/\)/g) || []).length;
    if (depth === 0 && opens > closes) { depth += opens - closes; continue; }
    if (depth > 0) { depth += opens - closes; if (depth < 0) depth = 0; continue; }
    lines.push(l);
  }

  let idx = 0;
  while (idx < lines.length && !lines[idx].trim()) idx++;
  const firstLine = (lines[idx] || '').trim();
  const title = isTitleLine(firstLine) ? firstLine : '';
  if (title) idx++;
  const date = parseDate(title, msgDateISO);
  let session_type = sessionTypeFrom(title.replace(/[\d\/\-.]+/g, ' '));

  const sets = [];
  const setCounters = {};
  const restByEx = {};
  const modifierByEx = {};
  let currentRaw = null;
  let supersetParts = null;
  let ctxWeight = null;
  let excluded = false;
  let pendingNote = '';     // commentary that appears before an exercise's first set
  const unknown = new Set();

  const pushSet = (rawName, nums, line) => {
    const { exercise, known } = resolveExercise(rawName, aliases);
    if (!known) unknown.add(rawName);
    const [mg, eq] = meta[exercise] || ['', ''];
    const f = flagsFrom(line);
    for (const n of nums) {
      setCounters[exercise] = (setCounters[exercise] || 0) + 1;
      let unit = n.unit;
      if (PER_SIDE_EXERCISES.has(exercise) && unit !== 'bw') unit = 'kg_per_side';
      if (unit === 'plates') unit = 'kg_per_side';
      const note = [pendingNote, f.note].filter(Boolean).join('; ');
      pendingNote = '';
      sets.push({
        date, session_id: '', gym, session_type,
        exercise, exercise_raw: rawName, muscle_group: mg, equipment: eq,
        set_no: setCounters[exercise], weight: n.weight, unit, reps: n.reps,
        pb_flag: f.pb_flag, proud: f.proud, effort: f.effort,
        delta_vs_prev: f.delta_vs_prev, note, source: SOURCE,
        rest_s: null, hold_s: n.hold_s || null, warmup: false,
      });
    }
  };

  for (; idx < lines.length; idx++) {
    const line = lines[idx].trim();
    if (!line) continue;
    if (TEMPLATE_LINE_RE.test(line)) continue;   // the template's recap and cap lines, not data
    if (DIDNT_DO_RE.test(line)) { excluded = true; warnings.push(`Excluded sets under "${line}"`); continue; }

    // rest period line: applies to the current exercise
    const rest = parseRest(line);
    if (rest != null && currentRaw) { restByEx[currentRaw] = rest; continue; }

    // "(Seated)" alone on a line: modifier for the current exercise
    const mod = line.match(MODIFIER_RE);
    if (mod && currentRaw) { modifierByEx[currentRaw] = mod[1].trim(); continue; }

    const ctx = line.match(/^(\d+(?:\.\d+)?)\s*kg\s*:?\s*$/i);
    if (ctx) { ctxWeight = parseFloat(ctx[1]); continue; }

    const labelled = line.match(/^([A-Za-z]{1,2})\s*:\s*(.+)$/);
    if (labelled && supersetParts && /x\s*\d|^\d/.test(labelled[2])) {
      const letter = labelled[1].toLowerCase();
      const part = supersetParts.find(p => p.toLowerCase().startsWith(letter)) || supersetParts[0];
      const nums = parseSetLine(labelled[2], ctxWeight);
      if (nums && !excluded) pushSet(part, nums, line);
      continue;
    }

    if (currentRaw) {
      const hold = parseHold(line, ctxWeight);
      if (hold) { if (!excluded) pushSet(currentRaw, [hold], line); continue; }
      const nums = parseSetLine(line, ctxWeight);
      if (nums) { if (!excluded) pushSet(currentRaw, nums, line); continue; }
    }

    // A line ending in a colon is always an exercise header, however long (12 Oct: an 8-word header was being read as
    // commentary and its sets landed under the previous exercise). Otherwise: short, no digits first, no sentence punctuation.
    const endsWithColon = /:\s*$/.test(line) && !/^\(/.test(line) && !/^\d/.test(line);
    const looksLikeHeader = endsWithColon || (!/^\d/.test(line) && line.split(/\s+/).length <= 6 && !/[.!?]\s|[.!?]$/.test(line.replace(/\.\.\./g, '')));
    if (!looksLikeHeader) {
      // commentary: belongs to the current exercise. If it has sets already, note on the last one; otherwise hold for its first set.
      const curEx = currentRaw ? resolveExercise(currentRaw, aliases).exercise : null;
      const last = sets.length ? sets[sets.length - 1] : null;
      if (last && curEx && last.exercise === curEx) last.note = [last.note, line].filter(Boolean).join('; ');
      else pendingNote = [pendingNote, line].filter(Boolean).join('; ');
      continue;
    }
    const name = cleanRawName(line);
    if (!name) continue;
    currentRaw = name;
    ctxWeight = null;
    pendingNote = '';
    supersetParts = name.includes('/') ? name.split('/').map(s => cleanRawName(s)) : null;
  }

  // rest periods, modifiers, warm-up flags per exercise
  for (const s of sets) {
    if (restByEx[s.exercise_raw] != null) s.rest_s = restByEx[s.exercise_raw];
    if (modifierByEx[s.exercise_raw]) s.note = [modifierByEx[s.exercise_raw].toLowerCase(), s.note].filter(Boolean).join('; ');
  }
  const byEx = {};
  for (const s of sets) (byEx[s.exercise] = byEx[s.exercise] || []).push(s);
  for (const group of Object.values(byEx)) flagWarmups(group);

  if (session_type === 'unknown' && sets.length) {
    const score = { push: 0, pull: 0, legs: 0 };
    const mgType = mg => /chest|shoulder|delt|tricep/.test(mg) ? 'push' : /back|bicep|lat|trap|forearm/.test(mg) ? 'pull' : /quad|ham|glute|calf|calves|adductor|posterior/.test(mg) ? 'legs' : null;
    for (const s of sets) { const t = mgType(s.muscle_group || ''); if (t) score[t]++; }
    const best = Object.entries(score).sort((a, b) => b[1] - a[1])[0];
    if (best[1] > 0) { session_type = best[0]; for (const s of sets) s.session_type = session_type; }
  }
  const session_id = `tg:${date}:${session_type}`;
  for (const s of sets) s.session_id = session_id;

  if (unknown.size) warnings.push(`New exercise names: ${[...unknown].join(', ')}`);

  const working = sets.filter(s => !s.warmup);
  const session = {
    date, session_id, gym, session_type, title,
    n_exercises: new Set(sets.map(s => s.exercise)).size,
    n_sets: working.length,
    total_volume: Math.round(working.reduce((a, s) => a + (s.unit === 'bw' || s.hold_s ? 0 : s.weight * s.reps), 0)),
    pbs: sets.filter(s => s.pb_flag).length,
    source: SOURCE, raw_note: text,
  };
  return { session, sets, warnings };
}

// ---------- formatting helpers ----------
const num = v => (v === '' || v == null) ? 0 : parseFloat(v) || 0;
const fmtW = (w, unit) => unit === 'bw' ? 'BW' : (unit === 'kg_per_side' ? `${num(w)}/side` : `${num(w)}kg`);
const fmtSet = s => s.hold_s ? `${fmtW(s.weight, s.unit)} hold ${s.hold_s}s` : `${fmtW(s.weight, s.unit)} x${num(s.reps)}`;
function fmtDate(iso, todayISO) {
  const d = DateTime.fromISO(iso);
  const sameYear = todayISO ? iso.slice(0, 4) === todayISO.slice(0, 4) : true;
  return d.toFormat(sameYear ? 'd MMM' : 'd MMM yyyy');
}
// sets of one exercise in one session, as "100kg x10, 100kg x10, 100kg x10" (warm-ups and holds dropped, weight repeated only when it changes)
function fmtSets(rows) {
  const work = rows.filter(r => !r.warmup && !num(r.hold_s)).sort((a, b) => num(a.set_no) - num(b.set_no));
  const parts = [];
  let lastW = null;
  for (const r of work) {
    const w = fmtW(r.weight, r.unit);
    parts.push(w === lastW ? `${num(r.reps)}` : `${w} x${num(r.reps)}`);
    lastW = w;
  }
  return parts.join(', ');
}
const topSet = rows => rows.filter(r => !r.warmup && !num(r.hold_s)).slice().sort((a, b) => (num(b.weight) - num(a.weight)) || (num(b.reps) - num(a.reps)))[0];
const isPerGym = eq => eq === 'machine' || eq === 'cable';

// load increment for the next step of double progression
function incrementFor(exercise, equipment, unit) {
  if (unit === 'kg_per_side') return 2.5;
  if (/squat|deadlift/i.test(exercise)) return 5;
  if (equipment === 'barbell' || equipment === 'bodyweight') return 2.5;
  if (equipment === 'dumbbell') return 2;
  return 5;   // machines and cables: one plate
}

// ---------- template generator ----------
// Rebuilds the user's note for a day type from the programme and the last session of that type at this gym.
// Order: programme_days.seq (focus lift first, then heavy compounds, then accessories), then anything done last
// time that the programme does not list (12 Oct), EXCEPT a stand-in: an exercise that replaced a programme
// exercise last time because the kit was taken (22 Oct, exercises.substitute_for, or the same muscle group as a
// programme exercise that was skipped). The primary keeps its slot and its recap line says what the stand-in did.
// Set lines: exactly target_sets working lines per exercise (never last session's count), warm-ups printed above
// them as last time, bodyweight written "BW x". The whole session is capped at SESSION_SET_CAP working sets:
// over the cap, accessories and finishers lose a set from the bottom up, and extras only fit if room is left.
// Each exercise's first line carries "(last: ... | aim ...)".
function buildTemplate({ dayType, todayISO, history, sessions, programmeDays, gym, aliases, meta, subs }) {
  subs = subs || {};
  // history rows, with the bodyweight warm-up rule applied retrospectively (stored rows predate it)
  const hist = history.filter(r => r.exercise).map(r => Object.assign({}, r));
  const grp = {};
  for (const r of hist) { const k = `${r.session_id}|${r.exercise}`; (grp[k] = grp[k] || []).push(r); }
  for (const g of Object.values(grp)) if (g.some(x => x.unit !== 'bw' && !num(x.hold_s))) for (const x of g) if (x.unit === 'bw' && !num(x.hold_s)) x.warmup = true;

  const dayRows = programmeDays.filter(p => p.day === dayType && p.status === 'active').sort((a, b) => num(a.seq) - num(b.seq));
  const rangeFor = ex => { const p = dayRows.find(x => x.exercise === ex); return p ? [num(p.rep_low), num(p.rep_high), num(p.target_sets) || 3] : [8, 12, 3]; };

  // last session of this type at this gym
  const typeSessions = sessions.filter(s => s.session_type === dayType && s.gym === gym).sort((a, b) => a.date < b.date ? 1 : -1);
  const last = typeSessions[0] || null;

  // per exercise: last session's rows (gym-scoped for machines) and all-time best
  const exRows = ex => {
    const eq = (meta[ex] || EX_META[ex] || ['', ''])[1];
    let rows = hist.filter(r => r.exercise === ex);
    if (isPerGym(eq)) rows = rows.filter(r => r.gym === gym);
    return rows;
  };
  const lastRowsFor = ex => {
    const rows = exRows(ex);
    if (!rows.length) return { rows: [], date: null };
    const date = rows.map(r => r.date).sort().slice(-1)[0];
    return { rows: rows.filter(r => r.date === date), date };
  };
  const bestFor = ex => {
    const rows = exRows(ex).filter(r => !r.warmup && !num(r.hold_s));
    return rows.length ? rows.slice().sort((a, b) => (num(b.weight) - num(a.weight)) || (num(b.reps) - num(a.reps)))[0] : null;
  };

  // prescription per exercise: what to do at the top load next time, over nSets working sets
  const prescribe = (ex, nSets) => {
    const { rows, date } = lastRowsFor(ex);
    const [lo, hi] = rangeFor(ex);
    const eq = (meta[ex] || EX_META[ex] || ['', ''])[1];
    if (!rows.length) return { load: null, unit: null, reps: lo, sets: nSets, topW: null, text: `new, start light, ${nSets} x ${lo}-${hi}` };
    const work = rows.filter(r => !r.warmup && !num(r.hold_s)).sort((a, b) => num(a.set_no) - num(b.set_no));
    const top = topSet(rows);
    const best = bestFor(ex);
    const lastStr = `last: ${fmtSets(rows)}`;
    if (!work.length || !top) return { load: null, unit: null, reps: lo, sets: nSets, topW: null, text: `${lastStr} | aim ${nSets} x ${lo}-${hi}` };
    const unit = top.unit;
    const topW = num(top.weight);
    const atTop = work.filter(r => num(r.weight) === topW);
    const minTop = Math.min(...atTop.map(r => num(r.reps)));
    let load = topW, reps, aim;
    if (unit === 'bw') {
      const minReps = Math.min(...work.map(r => num(r.reps)));
      reps = Math.min(hi, minReps + 1);
      aim = minReps >= hi ? `add weight, ${nSets} x ${lo}+` : `${nSets} x ${reps}+`;
    } else if (minTop < lo && work.some(r => num(r.weight) < topW && num(r.reps) >= lo)) {
      // fell short of the range at the top load: back to the heaviest load that made the range
      const back = work.filter(r => num(r.weight) < topW && num(r.reps) >= lo).sort((a, b) => num(b.weight) - num(a.weight))[0];
      load = num(back.weight);
      reps = Math.min(hi, num(back.reps) + 1);
      aim = `${fmtW(load, unit)} x${reps}+ all ${nSets} sets, ${fmtW(topW, unit)} was early`;
    } else if (atTop.length >= Math.min(2, nSets) && atTop.every(r => num(r.reps) >= hi)) {
      load = topW + incrementFor(ex, eq, unit);
      reps = Math.max(lo, Math.min(hi, minTop - 2));
      aim = `${fmtW(load, unit)} x${reps}+ all ${nSets} sets`;
    } else {
      reps = Math.min(hi, Math.max(minTop + 1, lo));
      aim = `${fmtW(topW, unit)} x${reps}+ all ${nSets} sets`;
    }
    const earlier = exRows(ex).some(r => r.date < date);
    const pb = earlier && best && best.date === date ? ' PB' : '';
    const beats = best && (num(best.weight) > num(top.weight) || (num(best.weight) === num(top.weight) && num(best.reps) > num(top.reps)));
    const bestStr = beats ? ` | best ${fmtSet(best)} ${fmtDate(best.date, todayISO)}` : '';
    return { load, unit, reps, sets: nSets, topW, text: `${lastStr}${pb} | aim ${aim}${bestStr}` };
  };

  const d = DateTime.fromISO(todayISO);
  const titleName = dayType[0].toUpperCase() + dayType.slice(1);
  const out = [`${titleName} ${d.toFormat('d/M/yy')}:`, ''];

  const emitExercise = (header, ex, rowsForStructure, nSets, standIn) => {
    const p = prescribe(ex, nSets);
    if (standIn) {
      // the primary was not done last time; say what the stand-in did so the recap is still complete
      const s = lastRowsFor(standIn);
      if (s.rows.length) p.text += ` | ${fmtDate(s.date, todayISO)} did ${standIn} instead: ${fmtSets(s.rows)}`;
    }
    out.push(header);
    out.push('');
    const rows = (rowsForStructure || []).slice().sort((a, b) => num(a.set_no) - num(b.set_no));
    const modifier = rows.length && /^(seated|lying|standing)/i.test(rows[0].note || '') ? rows[0].note.split(';')[0].trim() : null;
    if (modifier) { out.push(`(${modifier[0].toUpperCase() + modifier.slice(1)})`); out.push(''); }
    const warm = [], work = [];
    let seenTop = false;
    const eqEx = (meta[ex] || EX_META[ex] || ['', ''])[1];
    const lineFor = r => {
      if (p.unit === 'bw' || (r && r.unit === 'bw')) return 'BW x';
      if (p.load == null) return eqEx === 'bodyweight' ? 'BW x' : (r ? `${fmtW(r.weight, r.unit)} x` : 'x');   // no history: load left for the user
      if (!r || p.topW == null) return `${fmtW(p.load, p.unit)} x`;
      if (num(r.weight) >= Math.min(p.topW, p.load)) { seenTop = true; return `${fmtW(p.load, p.unit)} x`; }
      if (seenTop) return `${fmtW(p.load, p.unit)} x`;   // a lighter set after the top sets was a drop set, not a ramp: prescribe the top load
      return `${fmtW(r.weight, r.unit)} x`;              // ramp set before the top load: last time's load
    };
    for (const r of rows) {
      if (num(r.hold_s)) continue;
      if (r.warmup) { warm.push(`${fmtW(r.weight, r.unit)} x`); continue; }
      if (work.length < nSets) work.push(lineFor(r));
    }
    while (work.length < nSets) work.push(lineFor(null));
    out.push(`(${p.text})`); out.push('');
    if (warm.length) { out.push(...warm); out.push(''); }
    out.push(...work);
    const rest = rows.find(r => num(r.rest_s));
    if (rest) { out.push(''); out.push(num(rest.rest_s) % 60 === 0 ? `${num(rest.rest_s) / 60} min RP` : `${num(rest.rest_s)}s RP`); }
    out.push('');
  };

  // last session's rows give each exercise its header wording and set structure; the programme gives the order
  const lastRows = last ? hist.filter(r => r.session_id === last.session_id) : [];
  const lastOrder = [];
  for (const r of lastRows.slice().sort((a, b) => num(a.id) - num(b.id))) if (!lastOrder.includes(r.exercise)) lastOrder.push(r.exercise);
  const emitFor = (ex, nSets, standIn) => {
    const rows = lastRows.filter(r => r.exercise === ex);
    const header = ((rows.length && rows[0].exercise_raw) || ex).replace(/:?$/, ':');
    emitExercise(header[0].toUpperCase() + header.slice(1), ex, rows, nSets, standIn || null);
  };

  // stand-ins: which programme exercise did a last-session extra replace? Explicit rule first (exercises.substitute_for),
  // otherwise the same muscle group as a programme exercise that was not done last time.
  const programmeSet = new Set(dayRows.map(p => p.exercise));
  const mgOf = ex => (meta[ex] || EX_META[ex] || ['', ''])[0];
  const missed = dayRows.map(p => p.exercise).filter(e => !lastOrder.includes(e));
  const standInFor = ex => {
    if (programmeSet.has(ex)) return null;
    if (subs[ex] && programmeSet.has(subs[ex])) return subs[ex];
    const mg = mgOf(ex);
    return mg ? (missed.find(e => mgOf(e) === mg) || null) : null;
  };
  const standIns = {};   // programme exercise -> the exercise that stood in for it last time
  for (const ex of lastOrder) { const p = standInFor(ex); if (p && !standIns[p]) standIns[p] = ex; }

  // the plan: programme first, then extras that were not stand-ins; trimmed to the session cap
  const plan = dayRows.map(p => ({ ex: p.exercise, sets: num(p.target_sets) || 3, role: String(p.role || 'accessory').toLowerCase(), standIn: standIns[p.exercise] || null, extra: false }));
  const total = () => plan.reduce((a, x) => a + x.sets, 0);
  const cuts = [];
  const cuttable = x => x.role !== 'focus' && x.role !== 'primary';
  while (total() > SESSION_SET_CAP) {
    // a set off the bottom-most accessory that still has more than two sets; failing that, drop the bottom-most accessory
    let i = -1;
    for (let j = plan.length - 1; j >= 0; j--) if (cuttable(plan[j]) && plan[j].sets > 2) { i = j; break; }
    if (i >= 0) { plan[i].sets--; cuts.push(`${plan[i].ex} ${plan[i].sets} sets`); continue; }
    for (let j = plan.length - 1; j >= 0; j--) if (cuttable(plan[j])) { i = j; break; }
    if (i < 0) break;
    cuts.push(`${plan[i].ex} dropped`); plan.splice(i, 1);
  }
  const skipped = [];
  for (const ex of lastOrder) {
    if (programmeSet.has(ex) || standInFor(ex)) continue;
    const sets = rangeFor(ex)[2];
    if (total() + sets <= SESSION_SET_CAP) plan.push({ ex, sets, role: 'extra', standIn: null, extra: true });
    else skipped.push(ex);
  }
  for (const x of plan) emitFor(x.ex, x.sets, x.standIn);
  const capNotes = [];
  if (cuts.length) capNotes.push(`trimmed: ${[...new Set(cuts.map(c => c.replace(/ \d+ sets$/, '')))].map(e => cuts.filter(c => c.startsWith(e)).slice(-1)[0]).join(', ')}`);
  if (skipped.length) capNotes.push(`left out: ${skipped.join(', ')}`);
  if (capNotes.length) out.push(`(cap: ${SESSION_SET_CAP} working sets, ${total()} planned. ${capNotes.join('; ')})`);

  while (out.length && out[out.length - 1] === '') out.pop();
  return out.join('\n');
}
// ---------- end shared workout library ----------

// ---------- Parse and compare: node body ----------
const msg = $('Classify').first().json;
const history = $('Read workouts').all().map(i => i.json).filter(r => r.exercise);
let exRows = [];
try { exRows = $('Read exercises').all().map(i => i.json); } catch (e) { exRows = []; }

const aliases = {};
const meta = {};
for (const r of exRows) {
  if (!r.exercise) continue;
  const canon = String(r.exercise).trim();
  aliases[canon.toLowerCase()] = canon;
  if (r.aliases) for (const a of String(r.aliases).split('|')) { const k = normKey(a); if (k) aliases[k] = canon; }
  if (r.muscle_group || r.equipment) meta[canon] = [r.muscle_group || '', r.equipment || ''];
}
// aliases learned from history (most frequent mapping wins); a raw name that is just a modifier is ignored
const rawCounts = {};
for (const r of history) {
  if (!r.exercise_raw || MODIFIER_RE.test(r.exercise_raw)) continue;
  const k = normKey(String(r.exercise_raw));
  rawCounts[k] = rawCounts[k] || {};
  rawCounts[k][r.exercise] = (rawCounts[k][r.exercise] || 0) + 1;
  if (!meta[r.exercise] && (r.muscle_group || r.equipment)) meta[r.exercise] = [r.muscle_group || '', r.equipment || ''];
}
const learned = {};
for (const [k, counts] of Object.entries(rawCounts)) learned[k] = Object.entries(counts).sort((a, b) => b[1] - a[1])[0][0];
const allAliases = Object.assign({}, learned, aliases);

const parsed = parseWorkout(msg.text, msg.dateISO, { aliases: allAliases, meta });
const { session, sets, warnings } = parsed;
const today = msg.dateISO;

// duplicate guard: same id, or same date with mostly the same exercises
const sameDay = history.filter(r => r.date === session.date);
const todayEx = new Set(sets.map(s => s.exercise));
const overlap = [...new Set(sameDay.map(r => r.exercise))].filter(e => todayEx.has(e)).length;
const duplicate = history.some(r => r.session_id === session.session_id) || (todayEx.size > 0 && overlap >= Math.ceil(todayEx.size / 2));

// lifting sessions this week (Mon-Sun)
const d = DateTime.fromISO(session.date);
const weekStart = d.startOf('week').toISODate(), weekEnd = d.endOf('week').toISODate();
const weekSessions = new Set(history.filter(r => r.date >= weekStart && r.date <= weekEnd).map(r => r.session_id));
if (!duplicate) weekSessions.add(session.session_id);

// per-exercise line: today's working sets, then vs last session, then PB or best
const lines = [];
let autoPBs = 0;
for (const ex of [...new Set(sets.map(s => s.exercise))]) {
  const mine = sets.filter(s => s.exercise === ex);
  const eq = mine[0].equipment;
  const perGym = isPerGym(eq);
  let hist = history.filter(r => r.exercise === ex && r.session_id !== session.session_id && !r.warmup && !num(r.hold_s));
  if (perGym) hist = hist.filter(r => r.gym === session.gym);
  const top = topSet(mine);
  const setsStr = fmtSets(mine) || mine.map(fmtSet).join(', ');
  if (!top) { lines.push(`${ex}: ${mine.map(fmtSet).join(', ')}`); continue; }
  if (!hist.length) { lines.push(`${ex}: ${setsStr}. First time${perGym ? ' at ' + session.gym : ' logged'}.`); continue; }
  const best = hist.slice().sort((a, b) => (num(b.weight) - num(a.weight)) || (num(b.reps) - num(a.reps)))[0];
  const lastDate = hist.map(r => r.date).sort().slice(-1)[0];
  const lastRows = hist.filter(r => r.date === lastDate);
  const lastTop = topSet(lastRows);
  const isPB = num(top.weight) > num(best.weight) || (num(top.weight) === num(best.weight) && num(top.reps) > num(best.reps));
  if (isPB) {
    autoPBs++;
    for (const s of mine) if (!s.warmup && !s.hold_s && num(s.weight) === num(top.weight) && num(s.reps) === num(top.reps)) { s.pb_flag = 1; s.note = s.note ? s.note + '; auto PB' : 'auto PB'; }
  }
  let vs;
  if (num(top.weight) === num(lastTop.weight)) {
    const dr = num(top.reps) - num(lastTop.reps);
    vs = dr === 0 ? `Same as ${fmtDate(lastDate, today)}` : `${dr > 0 ? '+' : ''}${dr} reps vs ${fmtDate(lastDate, today)}`;
  } else {
    const dw = num(top.weight) - num(lastTop.weight);
    vs = `${dw > 0 ? '+' : ''}${dw}kg vs ${fmtDate(lastDate, today)} (${fmtSet(lastTop)})`;
  }
  const tail = isPB ? ` PB, was ${fmtSet(best)} ${fmtDate(best.date, today)}.` : (best.date === lastDate ? '.' : ` Best ${fmtSet(best)}, ${fmtDate(best.date, today)}.`);
  lines.push(`${ex}: ${setsStr}. ${vs}.${tail}`.replace(/\.\.$/, '.'));
}
session.pbs = sets.filter(s => s.pb_flag).length;

let reply;
if (duplicate) {
  reply = `Already have a ${session.session_type} session on ${fmtDate(session.date, today)} with the same exercises. Nothing added.`;
} else {
  const typeName = session.session_type[0].toUpperCase() + session.session_type.slice(1);
  const head = `Logged ${typeName} ${fmtDate(session.date, today)}. ${session.n_sets} working sets, ${session.n_exercises} exercises, ${session.total_volume.toLocaleString('en-GB')}kg. Lifting session ${weekSessions.size} this week.`;
  const pbLine = autoPBs ? `\n\n${autoPBs} PB${autoPBs > 1 ? 's' : ''}.` : '';
  const warn = warnings.length ? `\n\n${warnings.join('\n')}` : '';
  reply = `${head}\n\n${lines.join('\n')}${pbLine}${warn}`;
}

const sessionRow = {
  date: session.date, gym: session.gym, session_type: session.session_type, title: session.title,
  n_exercises: session.n_exercises, n_sets: session.n_sets, comments: warnings.join(' | '),
  date_source: session.title && /\d{1,2}[\/\-.]\d{1,2}[\/\-.]\d{2,4}/.test(session.title) ? 'title' : 'message',
  source: 'telegram', session_id: session.session_id, raw_note: session.raw_note,
};

return [{ json: { duplicate, sessionRow, sets, reply, warnings } }];

// n8n Code node: Log weight
// Input: Classify (weight_kg) and Read daily (history). Output: one item with
// the daily-tab columns to write (date, weight_kg, weight_7d_avg) plus reply.

const msg = $('Classify').first().json;
const weight = msg.payload.weight_kg;
let hist = [];
try { hist = $('Read daily').all().map(i => i.json).filter(r => r.date && r.weight_kg !== '' && r.weight_kg != null); } catch (e) {}

const num = v => parseFloat(v) || 0;
const d = DateTime.fromISO(msg.dateISO);
const inRange = (from, to) => hist.filter(r => r.date >= from && r.date <= to && r.date !== msg.dateISO).map(r => num(r.weight_kg));
const avg = a => a.length ? a.reduce((x, y) => x + y, 0) / a.length : null;

const thisWeek = inRange(d.minus({ days: 6 }).toISODate(), d.toISODate()).concat([weight]);
const lastWeek = inRange(d.minus({ days: 13 }).toISODate(), d.minus({ days: 7 }).toISODate());
const a1 = avg(thisWeek), a0 = avg(lastWeek);

const TARGET = Number('{{PHASE_TARGET_KG}}');   // phase target: in the real system this is a programme key
let trend;
if (a0 != null) trend = `7-day avg ${a1.toFixed(1)}kg, ${(a1 - a0) >= 0 ? '+' : ''}${(a1 - a0).toFixed(1)}kg vs last week.`;
else trend = `7-day avg ${a1.toFixed(1)}kg (${thisWeek.length} reading${thisWeek.length > 1 ? 's' : ''}).`;
const reply = `Weight ${weight}kg logged for ${d.toFormat('d MMM')}. ${trend} ${(a1 - TARGET).toFixed(1)}kg above the ${TARGET}kg target.`;

return [{ json: { date: msg.dateISO, weight_kg: weight, weight_7d_avg: Math.round(a1 * 100) / 100, reply } }];

// n8n Code node: Log tape
// Input: Classify (payload = {waist_navel_cm: 84.5, ...}) and Read measurements
// (history, one row per date). Output: one item with date plus the columns
// sent, and a reply comparing each to the previous reading.

const msg = $('Classify').first().json;
const vals = msg.payload;
let hist = [];
try { hist = $('Read measurements').all().map(i => i.json).filter(r => r.date); } catch (e) {}
hist.sort((a, b) => a.date < b.date ? 1 : -1);   // newest first

const num = v => parseFloat(v) || 0;
const label = c => c.replace(/_cm$/, '').replace(/_navel/, '').replace(/^l_/, 'left ').replace(/^r_/, 'right ').replace(/_/g, ' ');
const lines = [];
for (const [col, v] of Object.entries(vals)) {
  const prev = hist.find(r => r.date !== msg.dateISO && r[col] !== '' && r[col] != null);
  if (prev) {
    const dv = v - num(prev[col]);
    lines.push(`${label(col)} ${v}cm (${dv >= 0 ? '+' : ''}${dv.toFixed(1)} vs ${DateTime.fromISO(prev.date).toFormat('d MMM')})`);
  } else {
    lines.push(`${label(col)} ${v}cm (first reading)`);
  }
}
const reply = `Logged for ${DateTime.fromISO(msg.dateISO).toFormat('d MMM')}:\n${lines.join('\n')}`;

return [{ json: { date: msg.dateISO, ...vals, reply } }];

// n8n Code node: Build parse request
// Input: the meal text (from Transcribe or from Classify), plus Read foods.
// Output: one item with { body } for the Claude HTTP node, and the text.

const CLAUDE_MODEL = 'claude-sonnet-5-5';

function claudeRequest(system, userContent, maxTokens = 2000) {
  return { model: CLAUDE_MODEL, max_tokens: maxTokens, system, messages: [{ role: 'user', content: userContent }] };
}

const cls = $('Classify').first().json;
let text = cls.payload.voice ? ($('Transcribe').first().json.text || '') : (cls.payload.text || '');
text = String(text).trim();
let foods = [];
try { foods = $('Read foods').all().map(i => i.json).filter(r => r.name); } catch (e) {}

const libraryList = foods.map(f => {
  const al = f.aliases ? ` (also: ${f.aliases})` : '';
  const sv = f.serving_desc ? ` [usual serving: ${f.serving_desc} = ${f.serving_g}g]` : '';
  return `- ${f.name}${al}${sv}`;
}).join('\n') || '- (library is empty)';

const system = `You turn a spoken description of a meal into a structured list of food items.
Return ONLY a JSON array, no prose. Each element:
{"item_raw": "<the food as the user said it>", "search_term": "<short clean product name for a food database search, 1-4 words, brand first if known, obvious speech-to-text errors corrected (e.g. 'ala' -> 'Arla', 'fahge' -> 'Fage'), no flavour words unless essential>", "library_match": "<exact name from the library list, or null>", "qty_desc": "<quantity as said, e.g. '2', '80g', 'a bowl'>", "grams": <number or null>, "note": "<optional>"}
Rules:
- Match to the library by name OR by any of its aliases (the 'also:' list). A plain word that is an alias is a match ('butter', 'eggs', 'cappuccino'). Never force a match to a different food.
- grams: convert when you can. A library item said with a COUNT ('3 cappuccinos', 'two eggs', '2 bars') -> count x its usual serving grams (3 cappuccinos at 204g = 612). A library item said without a quantity -> its usual serving grams. '80g oats' -> 80; '200ml milk' -> 206. Leave null only when you really cannot tell.
- Split combined items ('porridge with honey' -> two items unless 'porridge' is a library item that already includes honey). A cappuccino, latte or flat white is ONE item (milk included), never split into coffee and milk.
- Keep brand names in item_raw when said.`;

const user = `Library:\n${libraryList}\n\nMeal description: "${text}"`;

return [{ json: { text, body: claudeRequest(system, user, 1500) } }];

// n8n Code node: Resolve items
// Input: Claude parse response. Looks up library matches; for unknowns,
// searches Open Food Facts (UK) and builds a second Claude request to pick
// the right product. Output: one item { items, unknowns, hasUnknowns, body }.

const CLAUDE_MODEL = 'claude-sonnet-5-5';
const num = v => (v === '' || v == null) ? 0 : (parseFloat(v) || 0);

function claudeRequest(system, userContent, maxTokens = 2000) {
  return { model: CLAUDE_MODEL, max_tokens: maxTokens, system, messages: [{ role: 'user', content: userContent }] };
}

// Pull the JSON out of a Claude text reply, whatever fences or prose surround it.
function claudeJSON(resp) {
  let text = (resp.content || []).filter(c => c.type === 'text').map(c => c.text).join('\n');
  text = text.replace(/```[a-z]*/gi, '').trim();
  const s = text.search(/[\[{]/);
  const e = Math.max(text.lastIndexOf(']'), text.lastIndexOf('}'));
  if (s < 0 || e < s) throw new Error('No JSON in model reply: ' + text.slice(0, 120));
  return JSON.parse(text.slice(s, e + 1));
}


const parsed = claudeJSON($input.first().json);
let foods = [];
try { foods = $('Read foods').all().map(i => i.json).filter(r => r.name); } catch (e) {}
const byName = {};
for (const f of foods) { byName[f.name.toLowerCase()] = f; if (f.aliases) for (const a of String(f.aliases).split('|')) byName[a.trim().toLowerCase()] = f; }

const items = [];
const unknowns = [];
for (const p of parsed) {
  let match = p.library_match ? byName[String(p.library_match).toLowerCase()] : null;
  if (!match) match = byName[String(p.item_raw || '').toLowerCase().trim()] || null;   // a plain alias said verbatim
  let grams = p.grams != null ? num(p.grams) : null;
  if (match && (grams == null || grams === 0) && num(match.serving_g) > 0) grams = num(match.serving_g);
  const it = { item_raw: p.item_raw, search_term: p.search_term || p.item_raw, qty_desc: p.qty_desc || '', grams, food: match || null, source: match ? 'library' : null };
  items.push(it);
  if (!match) unknowns.push(it);
}

// Open Food Facts search for each unknown: UK first, then worldwide, then a shorter term
const kcalOf = n => { if (!n) return null; if (n['energy-kcal_100g'] != null) return n['energy-kcal_100g']; if (n.energy_100g != null) return Math.round(n.energy_100g / 4.184); return null; };
const offSearch = async (term, uk) => {
  const q = encodeURIComponent(term);
  const url = `https://world.openfoodfacts.org/cgi/search.pl?search_terms=${q}&search_simple=1&action=process&json=1&page_size=8${uk ? '&tagtype_0=countries&tag_contains_0=contains&tag_0=united-kingdom' : ''}&fields=code,product_name,brands,nutriments,serving_size,serving_quantity`;
  try {
    const res = await this.helpers.httpRequest({ url, json: true, headers: { 'User-Agent': 'CoachEngineBot/1.0 (n8n)' } });
    return (res.products || []).map(pr => ({
      code: pr.code, name: pr.product_name, brand: pr.brands,
      per_100g: { kcal: kcalOf(pr.nutriments), protein: pr.nutriments && pr.nutriments.proteins_100g, carbs: pr.nutriments && pr.nutriments.carbohydrates_100g, fat: pr.nutriments && pr.nutriments.fat_100g, fibre: pr.nutriments && pr.nutriments.fiber_100g },
      serving: pr.serving_size || null, serving_g: pr.serving_quantity || null,
    })).filter(c => c.name && c.per_100g.kcal != null);
  } catch (e) { return []; }
};
const candidates = {};
for (const u of unknowns) {
  const term = (u.search_term || u.item_raw).replace(/[,.]/g, ' ').replace(/\s+/g, ' ').trim();
  const short = term.split(' ').slice(0, 2).join(' ');
  let c = await offSearch(term, true);
  if (!c.length) c = await offSearch(term, false);
  if (!c.length && short !== term) c = await offSearch(short, true);
  candidates[u.item_raw] = c.slice(0, 6);
}

let body = null;
if (unknowns.length) {
  const system = `You match foods a user mentioned to candidate products from Open Food Facts.
Return ONLY a JSON array, one element per unknown item, in the same order:
{"item_raw": "...", "match_index": <index into that item's candidates, or null>, "confidence": "high"|"medium"|"low", "grams": <number or null>, "reason": "<short>"}
Rules:
- Only give match_index with confidence high or medium when the candidate is clearly the same product or a generic equivalent with sensible nutrition values (kcal per 100g plausible for that food).
- Prefer the candidate whose brand matches what the user said. If the user named no brand and candidates are all branded versions of a generic food (e.g. eggs, chicken breast, banana, rice), a sensible generic candidate is fine.
- grams: the amount the user ate, converting from the quantity description if you can (use serving_g when the user said 'one' or 'a' of a packaged item). null if unknown.
- If no candidate fits, match_index null.`;
  const user = unknowns.map(u => `Item: "${u.item_raw}" (quantity: ${u.qty_desc || 'not stated'}, grams so far: ${u.grams ?? 'null'})\nCandidates:\n${(candidates[u.item_raw] || []).map((c, i) => `  [${i}] ${c.name}${c.brand ? ' (' + c.brand + ')' : ''}: per 100g ${c.per_100g.kcal} kcal, P ${c.per_100g.protein}, C ${c.per_100g.carbs}, F ${c.per_100g.fat}, fibre ${c.per_100g.fibre}; serving ${c.serving || '?'} (${c.serving_g || '?'}g)`).join('\n') || '  (none found)'}`).join('\n\n');
  body = claudeRequest(system, user, 1500);
}

return [{ json: { items, unknowns: unknowns.map(u => u.item_raw), candidates, hasUnknowns: unknowns.length > 0, body } }];

// n8n Code node: Finalise meal
// Runs after Claude match (if there were unknowns) or straight after Resolve.
// Produces foods rows (new OFF matches), food_log rows, pending rows (still unknown), the daily totals row,
// and the pieces Compose food reply assembles (blocks, asks, title).

const slug = s => String(s || '').toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '');
const num = v => (v === '' || v == null) ? 0 : (parseFloat(v) || 0);
const r1 = v => Math.round(v * 10) / 10;

function claudeJSON(resp) {
  let text = (resp.content || []).filter(c => c.type === 'text').map(c => c.text).join('\n');
  text = text.replace(/```[a-z]*/gi, '').trim();
  const s = text.search(/[\[{]/);
  const e = Math.max(text.lastIndexOf(']'), text.lastIndexOf('}'));
  if (s < 0 || e < s) throw new Error('No JSON in model reply: ' + text.slice(0, 120));
  return JSON.parse(text.slice(s, e + 1));
}

function macrosFor(food, grams) {
  const f = grams / 100;
  return {
    kcal: r1(num(food.per_100g_kcal) * f), protein_g: r1(num(food.per_100g_protein) * f),
    carbs_g: r1(num(food.per_100g_carbs) * f), fat_g: r1(num(food.per_100g_fat) * f), fibre_g: r1(num(food.per_100g_fibre) * f),
  };
}

function dayTotals(logRows) {
  const t = { kcal: 0, protein_g: 0, carbs_g: 0, fat_g: 0, fibre_g: 0 };
  for (const r of logRows) for (const k of Object.keys(t)) t[k] += num(r[k]);
  for (const k of Object.keys(t)) t[k] = Math.round(t[k]);
  return t;
}

function itemBlock(name, grams, mac, tag) {
  const g = Math.round(grams * 10) / 10;
  return `\u2022 ${name}, ${g}g\n   ${Math.round(mac.kcal)} kcal, ${r1(mac.protein_g)}g protein, ${r1(mac.fibre_g)}g fibre${tag ? '\n   ' + tag : ''}`;
}

function foodOutput(o) {
  return [{ json: { foodsRows: [], logRows: [], pendingRows: [], dailyRow: null, reply: '', blocks: [], asks: [], title: '', head: '', note: '', ...o } }];
}

function dailyRowFor(date, existingLog, newLogRows) {
  const all = existingLog.filter(r => r.date === date).concat(newLogRows);
  const t = dayTotals(all);
  return { row: { date, calories: t.kcal, protein_g: t.protein_g, carbs_g: t.carbs_g, fat_g: t.fat_g, fibre_g: t.fibre_g }, totals: t };
}


const cls = $('Classify').first().json;
const res = $('Resolve items').first().json;
const mealText = $('Build parse request').first().json.text;
let foods = [], logHist = [];
try { foods = $('Read foods').all().map(i => i.json).filter(r => r.name); } catch (e) {}
try { logHist = $('Read food_log').all().map(i => i.json).filter(r => r.date); } catch (e) {}

let matches = [];
if (res.hasUnknowns) { try { matches = claudeJSON($('Claude match').first().json); } catch (e) { matches = []; } }

const foodsRows = [], logRows = [], pendingRows = [], blocks = [], asks = [];
let n = 0;
const mkId = () => `${cls.dateISO}-${cls.timeHM.replace(':', '')}-${++n}`;

for (const it of res.items) {
  let food = it.food, grams = it.grams, source = it.source;
  if (!food) {
    const m = matches.find(x => x.item_raw === it.item_raw);
    const cands = res.candidates[it.item_raw] || [];
    if (m && m.match_index != null && cands[m.match_index] && m.confidence !== 'low') {
      const c = cands[m.match_index];
      food = {
        id: slug(c.name + (c.brand ? '-' + c.brand.split(',')[0] : '')), name: c.name, aliases: it.item_raw, brand: c.brand || '',
        per_100g_kcal: c.per_100g.kcal, per_100g_protein: c.per_100g.protein ?? '', per_100g_carbs: c.per_100g.carbs ?? '',
        per_100g_fat: c.per_100g.fat ?? '', per_100g_fibre: c.per_100g.fibre ?? '', serving_desc: c.serving || '', serving_g: c.serving_g || '',
        source: 'openfoodfacts', added: cls.dateISO,
      };
      if (!foods.find(f => f.id === food.id)) foodsRows.push(food);
      source = 'openfoodfacts';
      if ((grams == null || grams === 0) && m.grams) grams = num(m.grams);
      if ((grams == null || grams === 0) && num(food.serving_g)) grams = num(food.serving_g);
    }
  }
  if (food && grams) {
    const mac = macrosFor(food, grams);
    logRows.push({ id: mkId(), date: cls.dateISO, time: cls.timeHM, meal_text: mealText, item: it.item_raw, food_id: food.id, grams, ...mac, source });
    blocks.push(itemBlock(it.item_raw, grams, mac, source === 'openfoodfacts' ? `new: ${food.name}${food.brand ? ', ' + food.brand : ''}` : ''));
  } else if (food && !grams) {
    pendingRows.push({ id: `${cls.dateISO}-${slug(it.item_raw)}`, date: cls.dateISO, item_raw: it.item_raw, qty_desc: it.qty_desc, grams: '', status: 'open', created: `${cls.dateISO} ${cls.timeHM}` });
    asks.push(`${it.item_raw} (known, but how much? e.g. "food ${it.item_raw} 150g")`);
  } else {
    pendingRows.push({ id: `${cls.dateISO}-${slug(it.item_raw)}`, date: cls.dateISO, item_raw: it.item_raw, qty_desc: it.qty_desc, grams: grams || '', status: 'open', created: `${cls.dateISO} ${cls.timeHM}` });
    asks.push(it.item_raw);
  }
}

const { row: dailyRow } = dailyRowFor(cls.dateISO, logHist, logRows);
const title = logRows.length ? `\u2705 Logged ${logRows.length} item${logRows.length > 1 ? 's' : ''}` : '';
const reply = title ? `${title}\n\n${blocks.join('\n\n')}` : 'Nothing logged yet.';
return foodOutput({ foodsRows, logRows, pendingRows, dailyRow: logRows.length ? dailyRow : null, reply, blocks, asks, title });

// n8n Code node: Build label request
// Input: Photo to base64 (one item per photo in the album, json.b64 = the image). Output: ONE item { body } for Claude
// with every image, the merged caption, the open pending items and the food library. This node must NOT be set to execute once.
// 12 Oct: the photo can be a packaging label OR a plate of food; the model classifies it first (photo_type).

const CLAUDE_MODEL = 'claude-sonnet-5-5';   // change here if the API says the model is not found

const cls = $('Classify').first().json;
let pending = [], foods = [];
try { pending = $('Read pending L').all().map(i => i.json).filter(r => r.status === 'open'); } catch (e) {}
try { foods = $('Read foods L').all().map(i => i.json).filter(r => r.name); } catch (e) {}
let gate = {};
try { gate = $('Album gate').first().json || {}; } catch (e) {}
const caption = (gate.caption || cls.payload.caption || '').trim();

function jpegSize(buf) {
  let i = 2;
  while (i < buf.length - 9) {
    if (buf[i] !== 0xFF) { i++; continue; }
    const m = buf[i + 1];
    if (m >= 0xC0 && m <= 0xCF && m !== 0xC4 && m !== 0xC8 && m !== 0xCC) return { h: buf.readUInt16BE(i + 5), w: buf.readUInt16BE(i + 7) };
    const len = buf.readUInt16BE(i + 2);
    i += 2 + len;
  }
  return null;
}

const items = $input.all();
const content = [];
const debug = [];
for (let i = 0; i < items.length; i++) {
  const b64 = items[i].json.b64;
  if (!b64) continue;
  const buf = Buffer.from(b64, 'base64');
  debug.push({ i, file: (items[i].json.result || {}).file_path || null, bytes: buf.length, size: jpegSize(buf) });
  content.push({ type: 'image', source: { type: 'base64', media_type: 'image/jpeg', data: b64 } });
}
if (!content.length) throw new Error('No photo data came back from Telegram');
const nPhotos = content.length;

const num = v => (v === '' || v == null) ? 0 : (parseFloat(v) || 0);
const libraryList = foods.map(f => `- ${f.name}${f.aliases ? ' (also: ' + f.aliases + ')' : ''}: per 100g ${num(f.per_100g_kcal)} kcal, P ${num(f.per_100g_protein)}, C ${num(f.per_100g_carbs)}, F ${num(f.per_100g_fat)}, fibre ${num(f.per_100g_fibre)}${f.serving_g ? '; serving ' + f.serving_g + 'g' : ''}`).join('\n') || '- (library is empty)';

const system = `You read phone photos of food for a UK user and return ONLY JSON. All photos in one message show the SAME thing: either (A) a packaged product (front of pack and/or its nutrition table, any order) or (B) a meal on a plate or in a bowl (home-cooked or restaurant) with no packaging.
First decide photo_type: "label" when any photo shows packaging or a nutrition table; "meal" when the photos show prepared food and no packaging; "other" when it is neither (not food, or unreadable).
Return exactly:
{"photo_type": "label"|"meal"|"other", "table_photo": <1-based index of the photo with the nutrition table, or null>, "table_text": "<every line of the nutrition table as printed, or null>", "product_name": "<string or null>", "brand": "<string or null>", "per_100g": {"kcal": n, "protein": n, "carbs": n, "fat": n, "fibre": n} or null, "serving_desc": "<e.g. '1 pot (150g)' or null>", "serving_g": <n or null>, "portion_g": <n or null>, "portion_desc": "<string or null>", "pending_match": "<item_raw from the pending list, or null>", "readable": true|false, "meal": {"name": "<short dish name, 2-6 words>", "items": [{"name": "<component, generic UK name, cooked form>", "library_match": "<exact library name or null>", "grams": n, "per_100g": {"kcal": n, "protein": n, "carbs": n, "fat": n, "fibre": n}, "basis": "<one short line: how you sized it>"}], "confidence": "high"|"medium"|"low", "assumptions": "<one line, optional>"} or null}

LABEL rules (photo_type label; meal = null):
- First find the nutrition table (headings like 'Nutrition', 'Typical values', 'per 100g', 'Energy', 'Protein') and transcribe it into table_text. Then fill per_100g FROM that transcription. Phone photos: the table may be small in the frame; read it carefully.
- product_name: copy the product name printed on the packaging (front of pack or the heading on the label). If no name is printed in any photo, take it from the caption if the caption names the product; otherwise null. NEVER invent a name or infer one from the ingredients list.
- brand: the brand printed on the pack (e.g. M&S, Tesco, Müller), or null.
- per_100g: the per-100g column only (never per-serving), kcal not kJ. Report every value that is printed. UK labels often omit fibre: if there is no fibre line, fibre = 0. If carbs or fat are genuinely not printed, null for that one value only.
- readable: true whenever kcal AND protein per 100g can be read. false only if one of those two cannot be read from any photo (blurred, cut off, absent).
- serving: if the pack states a serving or the pack weight is a single portion (a yogurt pot, a bar), give serving_desc and serving_g (pack weight for a single-portion pack).
- portion: if the caption states an amount ('small handful', '2 bars', '150g', 'half the pack', 'one pot', 'one of these'), convert it to grams: use the label's own serving line when it fits (label says 'per small handful (25g)' and caption says 'small handful' -> 25), the pack weight for 'one pot' / 'the whole thing' / fractions, a sensible UK portion otherwise. portion_g = grams, portion_desc = the caption's wording. If the caption gives no amount, both null.
- pending_match: only if this product is clearly one of the pending items listed; a caption describing a fresh snack is not a pending match. Otherwise null.

MEAL rules (photo_type meal; the label fields null, readable false):
- The caption is the primary evidence for WHAT it is and HOW MUCH ('x1.5 chicken thighs' = 1.5 thighs; 'half of this' = half the plate; 'two of these' = two). Use the photos to size everything the caption does not quantify. Scale from the plate (a dinner plate is ~27cm, a pasta bowl ~22cm) and from the chicken, eggs or cutlery if visible.
- Itemise EVERY component you can see, plus the invisible ones a dish like this always carries: the oil or butter it was cooked in, sauce, pesto, cream, cheese, dressing. Never leave out the cooking fat; for a pan-fried or roasted dish assume at least 10-15g of oil or butter on the plate unless the caption says otherwise. One item per component (e.g. tagliatelle, chicken thigh, cherry tomatoes, pesto/oil sauce), not one item for the whole dish.
- grams: a realistic, as-eaten cooked weight for an adult's plate: the middle of the plausible range (the system adds its own safety margin, do not inflate). Pasta and rice as cooked weight. A boneless skinless chicken thigh cooked ~80g, with skin ~100g.
