// n8n Code node: Apply label
// Input: Claude label response. Two shapes (12 Oct):
//  - photo_type label: writes the food to the library, logs the portion from the caption or any pending item it belongs to.
//  - photo_type meal: a plate of food. Logs each component as a photo estimate with a deterministic safety margin
//    (SAFETY rules below), saves new components to the library as estimates, reuses library matches.
// Marks pending resolved, updates daily totals. Compose food reply lays it out.

// Conservative-estimate rule for photo meals (the user, 12 Oct): err slightly high on energy, slightly low on protein.
const SAFETY = { kcal_up: 1.10, macro_up: 1.10, protein_down: 0.95, fibre_down: 0.90, kcal_round: 10 };

const slug = s => String(s || '').toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '');
const num = v => (v === '' || v == null) ? 0 : (parseFloat(v) || 0);
const r1 = v => Math.round(v * 10) / 10;

function claudeJSON(resp) {
  let text = (resp.content || []).filter(c => c.type === 'text').map(c => c.text).join('\n');
  text = text.replace(/```[a-z]*/gi, '').trim();
  const s = text.search(/[\[{]/);
  const e = Math.max(text.lastIndexOf(']'), text.lastIndexOf('}'));
  if (s < 0 || e < s) throw new Error('No JSON in model reply: ' + text.slice(0, 120));
  return JSON.parse(text.slice(s, e + 1));
}

function macrosFor(food, grams) {
  const f = grams / 100;
  return {
    kcal: r1(num(food.per_100g_kcal) * f), protein_g: r1(num(food.per_100g_protein) * f),
    carbs_g: r1(num(food.per_100g_carbs) * f), fat_g: r1(num(food.per_100g_fat) * f), fibre_g: r1(num(food.per_100g_fibre) * f),
  };
}

// Photo estimates: calories, carbs and fat up 10% (kcal rounded UP to the next 10), protein down 5%, fibre down 10%.
function conservative(mac) {
  return {
    kcal: Math.ceil(mac.kcal * SAFETY.kcal_up / SAFETY.kcal_round) * SAFETY.kcal_round,
    protein_g: Math.floor(mac.protein_g * SAFETY.protein_down),
    carbs_g: r1(mac.carbs_g * SAFETY.macro_up), fat_g: r1(mac.fat_g * SAFETY.macro_up), fibre_g: r1(mac.fibre_g * SAFETY.fibre_down),
  };
}

function dayTotals(logRows) {
  const t = { kcal: 0, protein_g: 0, carbs_g: 0, fat_g: 0, fibre_g: 0 };
  for (const r of logRows) for (const k of Object.keys(t)) t[k] += num(r[k]);
  for (const k of Object.keys(t)) t[k] = Math.round(t[k]);
  return t;
}

function itemBlock(name, grams, mac, tag) {
  const g = Math.round(grams * 10) / 10;
  return `\u2022 ${name}, ${g}g\n   ${Math.round(mac.kcal)} kcal, ${r1(mac.protein_g)}g protein, ${r1(mac.fibre_g)}g fibre${tag ? '\n   ' + tag : ''}`;
}

function foodOutput(o) {
  return [{ json: { foodsRows: [], logRows: [], pendingRows: [], dailyRow: null, reply: '', blocks: [], asks: [], title: '', head: '', note: '', ...o } }];
}

function dailyRowFor(date, existingLog, newLogRows) {
  const all = existingLog.filter(r => r.date === date).concat(newLogRows);
  const t = dayTotals(all);
  return { row: { date, calories: t.kcal, protein_g: t.protein_g, carbs_g: t.carbs_g, fat_g: t.fat_g, fibre_g: t.fibre_g }, totals: t };
}


