// n8n Code node: Build estimate request
// "no label" (optionally followed by item names). Asks Claude for an educated
// estimate of each open pending item, using UK food composition knowledge.

// Shared helpers for the food path (embedded into each food Code node).
const CLAUDE_MODEL = 'claude-sonnet-5-5';   // change here if the API says the model is not found
const PROVISIONAL_TARGETS = { calories: 2100, protein_g: 170, fibre_g: 30 };   // used until programme tab has numbers

const slug = s => String(s || '').toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '');
const num = v => (v === '' || v == null) ? 0 : (parseFloat(v) || 0);
const r1 = v => Math.round(v * 10) / 10;

function claudeRequest(system, userContent, maxTokens = 2000) {
  return { model: CLAUDE_MODEL, max_tokens: maxTokens, system, messages: [{ role: 'user', content: userContent }] };
}

function claudeJSON(resp) {
  // resp: raw Anthropic messages response. Returns parsed JSON from the text.
  const text = (resp.content || []).filter(c => c.type === 'text').map(c => c.text).join('\n');
  const m = text.match(/```(?:json)?\s*([\s\S]*?)```/) || [null, text];
  const body = m[1].trim();
  const start = body.search(/[\[{]/);
  return JSON.parse(body.slice(start));
}

function macrosFor(food, grams) {
  const f = grams / 100;
  return {
    kcal: r1(num(food.per_100g_kcal) * f), protein_g: r1(num(food.per_100g_protein) * f),
    carbs_g: r1(num(food.per_100g_carbs) * f), fat_g: r1(num(food.per_100g_fat) * f), fibre_g: r1(num(food.per_100g_fibre) * f),
  };
}

function targetsFrom(programmeRows) {
  const t = { ...PROVISIONAL_TARGETS, provisional: true };
  const get = k => { const r = (programmeRows || []).find(x => x.key === k); return r && /^\d/.test(String(r.value)) ? num(r.value) : null; };
  const c = get('calorie_target'), p = get('protein_floor_g'), fb = get('fibre_floor_g');
  if (c) { t.calories = c; t.provisional = false; }
  if (p) t.protein_g = p;
  if (fb) t.fibre_g = fb;
  return t;
}

function dayTotals(logRows) {
  const t = { kcal: 0, protein_g: 0, carbs_g: 0, fat_g: 0, fibre_g: 0 };
  for (const r of logRows) for (const k of Object.keys(t)) t[k] += num(r[k]);
  for (const k of Object.keys(t)) t[k] = Math.round(t[k]);
  return t;
}

function totalsLine(totals, targets) {
  const left = targets.calories - totals.kcal;
  return `Today: ${totals.kcal} kcal (${left >= 0 ? left + ' left' : Math.abs(left) + ' over'} of ${targets.calories}${targets.provisional ? ', provisional' : ''}), protein ${totals.protein_g}g of ${targets.protein_g}g, fibre ${totals.fibre_g}g of ${targets.fibre_g}g.`;
}

