const num = v => parseFloat(v) || 0;
const pbSets = (d.sets || []).filter(s => s.pb_flag === 1 || s.pb_flag === '1');
if (!pbSets.length) return [];

// one line per lift: the best PB set for that exercise
const byEx = {};
for (const s of pbSets) {
  const cur = byEx[s.exercise];
  if (!cur || num(s.weight) > num(cur.weight) || (num(s.weight) === num(cur.weight) && num(s.reps) > num(cur.reps))) byEx[s.exercise] = s;
}
const fmtW = (w, unit) => unit === 'bw' ? 'bodyweight' : (unit === 'kg_per_side' ? `${w}kg per side` : `${w}kg`);
const pbs = Object.values(byEx).map(s => ({ exercise: s.exercise, set: `${fmtW(s.weight, s.unit)} x ${s.reps}` }));

// previous best from history (same scoping as Parse and compare: machines and cables compared within the gym)
let history = [];
try { history = $('Read workouts').all().map(i => i.json).filter(r => r.exercise && r.session_id !== d.sessionRow.session_id); } catch (e) {}
const gym = d.sessionRow && d.sessionRow.gym;
for (const p of pbs) {
  const s = byEx[p.exercise];
  const perGym = ['machine', 'cable'].includes(s.equipment);
  const hist = history.filter(r => r.exercise === p.exercise && (!perGym || r.gym === gym));
  if (hist.length) {
    const b = hist.slice().sort((a, b2) => (num(b2.weight) - num(a.weight)) || (num(b2.reps) - num(a.reps)))[0];
    p.previous_best = `${fmtW(b.weight, b.unit)} x ${b.reps} on ${b.date}${perGym ? ' at ' + gym : ''}`;
