// Night-quiz state machine. Handles three kinds from Classify: callback (button tap), quizreply (typed yes/no), note ("note: ...").
// Input: Read today Q (the last 3 rows of v_quiz_rows). Output: one item { mode, layout, step, text, keyboard, upsert, edit_message_id, answer, callback_id, stool_type, stool_row }.
// Shared quiz renderer (duplicated in the night digest workflow and the bot's Quiz step node; keep in sync)
const QUIZ = {
  2: { key: 'energy',   q: '⚡ Energy today?\n1 flat, 3 normal, 5 full of beans', scale: true },
  3: { key: 'mood',     q: '🙂 Mood?\n1 low, 3 fine, 5 great', scale: true },
  4: { key: 'soreness', q: '💢 Soreness?\n1 none, 3 noticeable, 5 wrecked', scale: true },
  5: { key: 'hunger',   q: '🍽️ Hunger?\n1 not hungry, 3 normal, 5 ravenous', scale: true },
  6: { key: 'substances', q: '🍃 Anything today?', opts: [['None','none'],['Alcohol','alcohol'],['THC','thc'],['Both','both']] },
  7: { key: 'bowel_count', q: '🚽 Bowel movements today?', count: true },
  8: { key: 'stool',    q: '💩 Quality? Bristol scale\n1-2 hard, 3-4 ideal, 5 soft, 6-7 loose', stool: true },
  9: { key: 'note',     q: '📝 Anything to note?\nType "note: ..." or tap Skip', opts: [['⏭️ Skip','skip']] },
};
const LAST = 10;   // step 10 = done
const btn = (text, data) => ({ text, additionalFields: { callback_data: data } });
const kb = (rows) => ({ rows: rows.map(r => ({ row: { buttons: r } })) });
const answeredLine = (row) => {
  const parts = [];
  if (row.energy) parts.push(`⚡${row.energy}`);
  if (row.mood) parts.push(`🙂${row.mood}`);
  if (row.soreness) parts.push(`💢${row.soreness}`);
  if (row.hunger) parts.push(`🍽️${row.hunger}`);
  if (row.substances) parts.push(`🍃 ${row.substances}`);
  if (row.bowel_count != null) parts.push(`🚽${row.bowel_count === 4 ? '4+' : row.bowel_count}`);
  if (row.stool_quiz) parts.push(`💩${row.stool_quiz}`);
  return parts.join('  ');
};
// Returns { text, keyboard, layout } for a step given the daily row (answers so far) and the step-1 summary text
function renderStep(step, row, summary, variant) {
  if (step === 1) {
    if (variant === 'change') {
      return { text: `${summary}\n\n✏️ Send the fix as a normal message (food, weight, workout), then tap Continue.`, keyboard: kb([[btn('▶️ Continue', 'q:1:ok')]]), layout: 'continue' };
    }
    return { text: `${summary}\n\nIs this all correct?`, keyboard: kb([[btn('✅ Correct', 'q:1:ok'), btn('✏️ Change something', 'q:1:change')]]), layout: 'confirm' };
  }
  if (step >= 2 && step < LAST) {
    const s = QUIZ[step];
    const head = answeredLine(row);
    const text = (head ? head + '\n\n' : '') + s.q;
    let buttons, layout;
    if (s.scale) { buttons = [[1,2,3,4,5].map(n => btn(String(n), `q:${step}:${n}`))]; layout = 'scale'; }
    else if (s.count) { buttons = [[0,1,2,3].map(n => btn(String(n), `q:${step}:${n}`)).concat([btn('4+', `q:${step}:4`)])]; layout = 'count'; }
    else if (s.stool) { buttons = [[1,2,3,4].map(n => btn(String(n), `q:${step}:${n}`)), [5,6,7].map(n => btn(String(n), `q:${step}:${n}`)).concat([btn('⏭️ Skip', `q:${step}:skip`)])]; layout = 'stool'; }
    else { buttons = [s.opts.map(([t, v]) => btn(t, `q:${step}:${v}`))]; layout = step === 6 ? 'subs' : 'skip'; }
    return { text, keyboard: kb(buttons), layout };
  }
  // step LAST: done
  const head = answeredLine(row);
  const noteLine = row.note ? `\n📝 ${row.note}` : '';
  return { text: `${head}${noteLine}\n\n✅ All recorded. Night.`, keyboard: null, layout: 'final' };
}


const cls = $('Classify').first().json;
const p = cls.payload || {};
let rows = [];
try { rows = $('Read today Q').all().map(i => i.json).filter(r => r && r.date); } catch (e) {}
const n = v => (v == null || v === '' ? null : Number(v));

let mode = 'none', text = '', keyboard = null, layout = 'ignore', step = 0, upsert = { date: cls.dateISO }, edit_message_id = null, answer = '', stool_type = null;

if (cls.kind === 'callback') {
  const row = rows.find(r => String(r.quiz_msg_id) === String(p.message_id));
  const m = /^q:(\d+):(.+)$/.exec(p.data || '');
  if (!row || !m) {
    answer = 'That one is closed';
  } else {
    const tapStep = Number(m[1]), val = m[2], cur = n(row.quiz_step);
    edit_message_id = row.quiz_msg_id;
    if (tapStep !== cur || cur >= LAST) {
      answer = 'Already answered';
    } else {
      const summary = (p.message_text || '').split(/\n\n(?:Is this all correct\?|✏️ Send the fix)/)[0];
      if (tapStep === 1 && val === 'change') {
        const r = renderStep(1, row, summary, 'change');
        text = r.text; keyboard = r.keyboard; layout = r.layout; step = 1; mode = 'edit'; upsert = { date: row.date }; answer = 'Send the fix, then Continue';
      } else {
        let next = tapStep + 1;
        const patch = { date: row.date, quiz_step: next };
        if (tapStep >= 2 && tapStep <= 5) patch[QUIZ[tapStep].key] = Number(val);
        if (tapStep === 6) patch.substances = val;
        if (tapStep === 7) { patch.bowel_count = Number(val); if (patch.bowel_count === 0) { next = 9; patch.quiz_step = 9; } }   // no movements: skip the quality step
        if (tapStep === 8 && val !== 'skip') { stool_type = Number(val); row.stool_quiz = stool_type; }
        if (next === LAST) patch.day_status = 'confirmed';
        const merged = Object.assign({}, row, patch);
        const r = renderStep(next, merged, summary);
        text = r.text; keyboard = r.keyboard; layout = r.layout; step = next; mode = 'edit'; upsert = patch; answer = next === LAST ? 'Recorded' : '';
      }
    }
  }
} else if (cls.kind === 'quizreply') {
  const row = rows.find(r => r.day_status === 'open' && n(r.quiz_step) === 1 && r.quiz_msg_id);
  if (!row) {
    mode = 'send'; text = 'Nothing open to confirm right now.';
  } else if (/^(yes|y|yep|yeah|correct|ok|okay|all good)/i.test(cls.text.trim())) {
    const patch = { date: row.date, quiz_step: 2 };
    const r = renderStep(2, Object.assign({}, row, patch), '');
    text = r.text; keyboard = r.keyboard; layout = r.layout; step = 2; mode = 'edit'; upsert = patch; edit_message_id = row.quiz_msg_id;
  } else {
    mode = 'send'; text = '✏️ Send the fix as a normal message (food, weight, workout), then reply yes.';
  }
} else if (cls.kind === 'note') {
  const row = rows.find(r => r.date === cls.dateISO) || { date: cls.dateISO };
  const patch = { date: row.date, note: p.text };
  if (n(row.quiz_step) === 9 && row.quiz_msg_id) {
    patch.quiz_step = LAST; patch.day_status = 'confirmed';
    const r = renderStep(LAST, Object.assign({}, row, patch), '');
    text = r.text; keyboard = null; layout = 'final'; step = LAST; mode = 'edit'; edit_message_id = row.quiz_msg_id;
  } else {
    mode = 'send'; text = '📝 Noted.';
  }
  upsert = patch;
}

if (mode === 'send') layout = 'send';
return [{ json: { mode, layout, step, text, keyboard, upsert, edit_message_id, answer, callback_id: p.callback_id || '', stool_type, stool_row: stool_type ? { date: upsert.date, bristol_type: stool_type, source: 'quiz' } : null } }];

