// n8n Code node: Quiz open?
// Runs after any logging reply. If tonight's quiz has been sent and not finished, pass through so it is re-sent
// with the updated record (the user, 12 Oct: the quiz must come back after every message until he completes it).
const cls = $('Classify').first().json;
if (!['food', 'label', 'nolabel', 'workout', 'weight', 'tape', 'stool'].includes(cls.kind)) return [];
const rows = $input.all().map(i => i.json).filter(r => r && r.date);
const r = rows[0];
if (!r || !r.quiz_msg_id) return [];
const step = Number(r.quiz_step || 0);
if (step < 1 || step >= 10 || r.day_status === 'confirmed') return [];
return [{ json: { date: r.date, old_msg_id: r.quiz_msg_id, step } }];

// n8n Code node: Build quiz refresh
// Same deterministic step-1 summary as Build night quiz in the digests workflow (keep the summary lines in sync).
const ctx = $input.first().json || {};
const q = $('Quiz open?').first().json;
const t = ctx.today || {};
const log = ctx.today_log || [];
const sess = ctx.today_sessions || [];
const plan = ctx.today_plan || {};
const d = DateTime.now().setZone('Europe/London');
const lines = [`🌙 ${d.toFormat('ccc d MMM')}`];
lines.push(t.weight_kg ? `⚖️ ${Number(t.weight_kg).toFixed(1)}kg` : '⚖️ No weigh-in logged');
if (log.length || t.calories) {
  lines.push(`🍽️ ${Math.round(t.calories || 0)} kcal, ${Math.round(t.protein_g || 0)}g protein, ${log.length} item${log.length === 1 ? '' : 's'} (target ${plan.kcal_target} / ${plan.protein_floor_g})`);
} else {
  lines.push('🍽️ No food logged');
}
if (sess.length) lines.push(`🏋️ ${sess.map(s => `${s.type} session, ${s.sets} sets`).join('; ')}`);
else if (t.cardio_type) lines.push(`🚴 ${t.cardio_type}${t.cardio_mins ? ', ' + t.cardio_mins + ' min' : ''}`);
else lines.push(`🏋️ No training logged (${plan.day_type} day)`);
if (ctx.today_stool && ctx.today_stool.length) lines.push(`💩 ${ctx.today_stool.map(x => 'type ' + x).join(', ')}`);
if (ctx.open_pending && ctx.open_pending.length) lines.push(`❓ Still unresolved: ${ctx.open_pending.map(p => p.item).join(', ')}`);
const summary = lines.join('\n');
return [{ json: { text: `${summary}\n\n🔄 Updated. Is this all correct?`, date: q.date || d.toISODate(), old_msg_id: q.old_msg_id } }];
